@Component("model-handler")
@ProcessingGroup("model-processing-group")
public class ModelEventHandler {
	
	// core constructor
	ModelEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateModelEvent
     */
    @EventHandler
    public void handle( CreateModelEvent event) {
        entityManager.persist(new Model(event.getModelId(), event.getName(), event.getTaskDescription(), event.getWorkspace(), event.getVersions(), event.getFeatureSets(), event.getExperiments(), event.getTags(), event.getModelType()));
    }

    /*
     * @param	event UpdateModelEvent
     */
    @EventHandler
    public Model handle( UpdateModelEvent event) {
    	entityManager.merge(new Model(event.getModelId(), event.getName(), event.getTaskDescription(), event.getWorkspace(), event.getVersions(), event.getFeatureSets(), event.getExperiments(), event.getTags(), event.getModelType()));
    }
    
    /*
     * @param	event DeleteModelEvent
     */
    @EventHandler
    public void on( DeleteModelEvent event) {
    	Model entity = new Model();
   
    	// ------------------------------------------
    	// apply the ModelId
    	// ------------------------------------------
    	entity.setModelId( event.getModelId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ModelRepository modelEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ModelEventHandler.class.getName());

}
